# ============================================================
# 1. Prompt Template - 提示词模板引擎
# ============================================================
class PromptTemplate:
    def __init__(self, template, input_variables=None, few_shot=None):
        self.template = template
        self.input_variables = input_variables or []
        self.few_shot = few_shot or []
        if not self.input_variables:
            self.input_variables = list(set(
                re.findall(r"\{(\w+)\}", template)
            ))

    def format(self, **kwargs):
        # Few-shot
        if self.few_shot:
            lines = []
            for ex in self.few_shot:
                lines.append(f"Example Input: {ex.get('input','')}")
                lines.append(f"Example Output: {ex.get('output','')}")
            examples = "\n".join(lines)
            result = self.template.replace("{examples}", examples)
        else:
            result = self.template
        for k, v in kwargs.items():
            result = result.replace("{" + k + "}", str(v))
        return result

    def __repr__(self):
        return f"PromptTemplate(variables={self.input_variables})"


