# 2. LLM Wrapper - 大语言模型封装（模拟）
# ============================================================
class BaseLLM(ABC):
    @abstractmethod
    def generate(self, prompt, **kwargs):
        pass

    def __call__(self, prompt, **kwargs):
        return self.generate(prompt, **kwargs)


class FakeLLM(BaseLLM):
    """模拟 LLM，根据关键词生成回复，用于演示"""
    def __init__(self, model_name="fake-gpt-4"):
        self.model_name = model_name
        self.call_count = 0
        self.total_tokens = 0

    def generate(self, prompt, temperature=0.7, max_tokens=500, **kwargs):
        self.call_count += 1
        prompt_len = len(prompt)
        tokens = prompt_len // 2
        self.total_tokens += tokens
        # 根据提示词内容生成"伪回复"
        if "翻译" in prompt:
            reply = f"[FakeLLM 翻译结果] 这是一段模拟翻译输出 (由 {self.model_name} 生成)"
        elif "摘要" in prompt:
            reply = f"[FakeLLM 摘要结果] 文档的核心内容是关于 AI 和大语言模型的发展 (由 {self.model_name} 生成)"
        elif "代码" in prompt or "python" in prompt.lower():
            reply = '```python\ndef hello():\n    print("Hello, LangChain!")\n```'
        elif "JSON" in prompt:
            reply = '{"name": "张三", "age": 25, "skills": ["Python", "AI"]}'
        else:
            reply = f"[FakeLLM] 收到你的问题，这是一段模拟回复。模型: {self.model_name}, 输入 tokens: {tokens}"
        return LLMResponse(
            text=reply,
            model=self.model_name,
            usage={"prompt_tokens": tokens, "completion_tokens": len(reply) // 2, "total_tokens": tokens + len(reply) // 2},
        )


@dataclass
class LLMResponse:
    text: str
    model: str = ""
    usage: dict = field(default_factory=dict)
    def __str__(self):
        return self.text


# ============================================================
# 3. Memory - 对话记忆系统
# ============================================================
class BaseMemory(ABC):
    @abstractmethod
    def load_memory(self, queries):
        pass

    @abstractmethod
    def save_memory(self, query, response):
        pass


class ConversationBufferMemory(BaseMemory):
    """缓冲记忆：保存所有历史对话"""
    def __init__(self):
        self.history = []

    def load_memory(self, queries=None):
        if not self.history:
            return ""
        lines = []
        for q, r in self.history:
            lines.append(f"Human: {q}")
            lines.append(f"AI: {r}")
        return "\n".join(lines)

    def save_memory(self, query, response):
        self.history.append((query, response))

    def clear(self):
        self.history = []

    def __repr__(self):
        return f"ConversationBufferMemory({len(self.history)} messages)"


class ConversationSummaryMemory(BaseMemory):
    """摘要记忆：用 LLM 将历史压缩为摘要"""
    def __init__(self, llm):
        self.llm = llm
        self.summary = ""

    def load_memory(self, queries=None):
        return self.summary

    def save_memory(self, query, response):
        combined = f"{self.summary}\nHuman: {query}\nAI: {response}" if self.summary else f"Human: {query}\nAI: {response}"
        prompt = f"请用一句话总结以下对话：\n{combined}"
        self.summary = str(self.llm.generate(prompt))

    def clear(self):
        self.summary = ""

    def __repr__(self):
        return f"ConversationSummaryMemory(summary_len={len(self.summary)})"


class ConversationBufferWindowMemory(BaseMemory):
    """窗口记忆：只保留最近 k 轮"""
    def __init__(self, k=5):
        self.k = k
        self.history = []

    def load_memory(self, queries=None):
        recent = self.history[-self.k:]
        if not recent:
            return ""
        lines = []
        for q, r in recent:
            lines.append(f"Human: {q}")
            lines.append(f"AI: {r}")
        return "\n".join(lines)

    def save_memory(self, query, response):
        self.history.append((query, response))
        if len(self.history) > self.k:
            self.history = self.history[-self.k:]

    def __repr__(self):
        return f"BufferWindowMemory(k={self.k}, stored={len(self.history)})"


# ============================================================
# 4. Chains - 链式调用
# ============================================================
class Chain(ABC):
    @abstractmethod
    def run(self, inputs, **kwargs):
        pass


class LLMChain(Chain):
    """LLM 链：Prompt + LLM 组合"""
    def __init__(self, llm, prompt, memory=None, output_key="text"):
        self.llm = llm
        self.prompt = prompt
        self.memory = memory
        self.output_key = output_key

    def run(self, inputs, **kwargs):
        # 加载记忆上下文
        context = ""
        if self.memory:
            context = self.memory.load_memory()
        full_inputs = {**inputs}
        if context and "history" not in full_inputs:
            full_inputs["history"] = context
        # 格式化 prompt
        formatted = self.prompt.format(**full_inputs)
        # 调用 LLM
        response = self.llm.generate(formatted, **kwargs)
        result = str(response)
        # 保存到记忆
        if self.memory:
            query = inputs.get("query", inputs.get("question", str(inputs)))
            self.memory.save_memory(query, result)
        return result


class SequentialChain(Chain):
    """顺序链：将多个链串联，前一个的输出作为后一个的输入"""
    def __init__(self, chains, input_key, output_key):
        self.chains = chains
        self.input_key = input_key
        self.output_key = output_key

    def run(self, inputs, **kwargs):
        current = inputs
        for chain in self.chains:
            current = {self.output_key: chain.run(current, **kwargs)}
        return current.get(self.output_key, "")


class TransformChain(Chain):
    """转换链：对数据进行自定义转换"""
    def __init__(self, transform_fn):
        self.transform_fn = transform_fn

    def run(self, inputs, **kwargs):
        return self.transform_fn(inputs)


# ============================================================
# 5. Output Parsers - 输出解析器
# ============================================================
class BaseOutputParser(ABC):
    @abstractmethod
    def parse(self, text):
        pass


class JsonOutputParser(BaseOutputParser):
    def parse(self, text):
        # 尝试从文本中提取 JSON
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group())
            except json.JSONDecodeError:
                pass
        return {"raw": text}


class StructuredOutputParser(BaseOutputParser):
    def __init__(self, schema):
        self.schema = schema  # {"field_name": "type"}

    def parse(self, text):
        result = {}
        for field_name, field_type in self.schema.items():
            pattern = rf"{field_name}[:\s]*(.+?)(?:\n|$)"
            match = re.search(pattern, text)
            if match:
                val = match.group(1).strip()
                if field_type == "int":
                    result[field_name] = int(re.search(r"\d+", val).group()) if re.search(r"\d+", val) else 0
                elif field_type == "float":
                    result[field_name] = float(re.search(r"[\d.]+", val).group()) if re.search(r"[\d.]+", val) else 0.0
                else:
                    result[field_name] = val
            else:
                result[field_name] = None
        return result


class CommaSeparatedListParser(BaseOutputParser):
    def parse(self, text):
        items = [item.strip() for item in text.split(",") if item.strip()]
        return items


# ============================================================
# 6. Tools and Agents - 工具调用与智能代理
# ============================================================
class Tool:
    """工具基类"""
    def __init__(self, name, description, func):
        self.name = name
        self.description = description
        self.func = func

    def run(self, *args, **kwargs):
        return self.func(*args, **kwargs)

    def __repr__(self):
        return f"Tool(name='{self.name}')"


class CalculatorTool(Tool):
    def __init__(self):
        super().__init__(
            name="calculator",
            description="执行数学计算，输入数学表达式",
            func=self._calculate
        )

    def _calculate(self, expression):
        try:
            # 安全计算（只允许基本数学运算）
            allowed = set("0123456789+-*/.() ")
            if all(c in allowed for c in expression):
                result = eval(expression)
                return f"计算结果: {expression} = {result}"
            return "错误：不支持的表达式"
        except Exception as e:
            return f"计算错误: {e}"


class SearchTool(Tool):
    def __init__(self):
        super().__init__(
            name="search",
            description="搜索信息，输入搜索关键词",
            func=self._search
        )

    def _search(self, query):
        return f"[搜索结果] 关于 '{query}' 的模拟搜索结果：这是一条来自搜索引擎的模拟信息。"


class DateTimeTool(Tool):
    def __init__(self):
        super().__init__(
            name="datetime",
            description="获取当前日期和时间",
            func=self._get_datetime
        )

    def _get_datetime(self, _=None):
        return f"当前时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"


class Agent(ABC):
    """智能代理基类"""
    def __init__(self, llm, tools, prompt=None, max_iterations=5):
        self.llm = llm
        self.tools = {t.name: t for t in tools}
        self.prompt = prompt
        self.max_iterations = max_iterations

    @abstractmethod
    def decide_action(self, observation):
        pass

    def run(self, query):
        print(f"\n[Agent] 收到任务: {query}")
        for i in range(self.max_iterations):
            print(f"\n--- 迭代 {i + 1} ---")
            action = self.decide_action(query)
            if action == "FINISH":
                print("[Agent] 任务完成!")
                return self._final_answer
            tool_name, tool_input = action
            print(f"[Agent] 调用工具: {tool_name}({tool_input})")
            if tool_name in self.tools:
                result = self.tools[tool_name].run(tool_input)
            else:
                result = f"错误: 工具 '{tool_name}' 不存在"
            print(f"[Agent] 工具返回: {result}")
            query = f"之前的查询: {query}\n工具 {tool_name} 的结果: {result}\n请继续处理。"
        return "达到最大迭代次数，停止。"


class SimpleReActAgent(Agent):
    """简化的 ReAct Agent（Reasoning + Acting）"""
    def __init__(self, llm, tools, max_iterations=5):
        super().__init__(llm, tools, max_iterations=max_iterations)
        self._final_answer = ""
        self._tool_descriptions = "\n".join(
            f"- {t.name}: {t.description}" for t in tools
        )

    def decide_action(self, observation):
        prompt = f"""你是一个智能助手，可以使用以下工具：
{self._tool_descriptions}

任务: {observation}

如果需要使用工具，请回复:
Thought: <你的思考>
Action: <工具名>
Action Input: <输入>

如果已经有足够信息，请回复:
Thought: <你的思考>
Final Answer: <最终答案>
"""
        response = str(self.llm.generate(prompt))
        print(f"[ReAct] LLM 输出:\n{response}")
        # 解析
        final_match = re.search(r"Final Answer:\s*(.+)", response, re.DOTALL)
        if final_match:
            self._final_answer = final_match.group(1).strip()
            return "FINISH"
        action_match = re.search(r"Action:\s*(\w+)", response)
        input_match = re.search(r"Action Input:\s*(.+)", response, re.DOTALL)
        if action_match and input_match:
            return (action_match.group(1), input_match.group(1).strip())
        self._final_answer = response
        return "FINISH"


