class RecursiveCharacterTextSplitter:
    def __init__(self, chunk_size=200, chunk_overlap=50, separators=None):
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = separators or ["\n\n", "\n", "。", ".", " "]

    def split_text(self, text):
        chunks = []
        self._split_recursive(text, chunks)
        return chunks

    def _split_recursive(self, text, chunks):
        if len(text) <= self.chunk_size:
            chunks.append(text)
            return
        for sep in self.separators:
            if sep in text:
                parts = text.split(sep)
                current = ""
                for part in parts:
                    if len(current) + len(part) + len(sep) <= self.chunk_size:
                        current += part + sep
                    else:
                        if current:
                            chunks.append(current.strip())
                        current = part + sep
                if current.strip():
                    # 如果还是太长，递归分割
                    if len(current) > self.chunk_size:
                        self._split_recursive(current, chunks)
                    else:
                        chunks.append(current.strip())
                return
        # fallback: 按字符切分
        for i in range(0, len(text), self.chunk_size - self.chunk_overlap):
            chunks.append(text[i:i + self.chunk_size])
