        for _ in range(max(1, self.w//3)):
            p = (random.randint(0,self.w-1), random.randint(0,self.h-1))
            if p not in self.obs and p != tuple(self.goal): self.traps.add(p)
        return np.array(self.pos, dtype=np.float32)
    def step(self, action):
        d = [(-1,0),(1,0),(0,-1),(0,1)][action]
        nx = max(0, min(self.w-1, self.pos[0]+d[0]))
        ny = max(0, min(self.h-1, self.pos[1]+d[1]))
        if (nx,ny) not in self.obs: self.pos = [nx,ny]
        self.steps += 1
        reward = -0.1; done = False
        if tuple(self.pos) == tuple(self.goal): reward = 10.0; done = True
        elif tuple(self.pos) in self.traps: reward = -5.0
